import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.DMXcdKmJ.js";const p=JSON.parse('{"title":"管理接入源","description":"在数据中心查找、新建和维护接入连接，选择内置库或外部服务，并分别确认保存和连接测试。","frontmatter":{"title":"管理接入源","description":"在数据中心查找、新建和维护接入连接，选择内置库或外部服务，并分别确认保存和连接测试。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/access-sources.md","filePath":"zh/使用指南/管理接入源.md"}'),o={name:"zh/guide/access-sources.md"};function h(s,t,i,n,l,u){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="管理接入源" tabindex="-1">管理接入源 <a class="header-anchor" href="#管理接入源" aria-label="Permalink to &quot;管理接入源&quot;">​</a></h1><p>入口是 <strong>“工程管理” → 目标工程 → “数据中心” → “接入源”</strong>。使用有工程配置权限的组织账号；外部服务的地址、账号、证书和访问授权应先由负责人提供。</p><p>接入源用于保存工程访问数据服务的配置。工业协议设备另在<a href="/induframe-docs/zh/guide/industrial-connections.html">工业采集</a>维护，不在这里选择 MySQL 等类型代替设备协议。</p><h2 id="_1-选择类型" tabindex="-1">1. 选择类型 <a class="header-anchor" href="#_1-选择类型" aria-label="Permalink to &quot;1. 选择类型&quot;">​</a></h2><p>点击 <strong>“新建连接”</strong>，先选择接入类型，再填写对应配置。</p><table tabindex="0"><thead><tr><th>类型</th><th>用途与说明</th></tr></thead><tbody><tr><td>内置运行库</td><td>关系库、时序库、实时库、消息中心，见<a href="/induframe-docs/zh/guide/builtin-stores.html">使用内置库</a></td></tr><tr><td>MySQL</td><td>外部 MySQL 数据库，见<a href="/induframe-docs/zh/guide/mysql.html">连接 MySQL</a></td></tr><tr><td>PostgreSQL</td><td>外部 PostgreSQL 数据库，见<a href="/induframe-docs/zh/guide/postgresql.html">连接 PostgreSQL</a></td></tr><tr><td>SQL Server</td><td>外部 SQL Server 数据库，见<a href="/induframe-docs/zh/guide/sqlserver.html">连接 SQL Server</a></td></tr><tr><td>MQTT、Kafka</td><td>消息服务的连接、订阅和相应配置</td></tr><tr><td>HTTP、WebSocket</td><td>接口请求或会话消息配置，创建连接后还需配置具体内容</td></tr><tr><td>Redis</td><td>外部实时数据与缓存连接</td></tr><tr><td>TDengine</td><td>外部时序数据库连接</td></tr></tbody></table><p>页面列出某种类型，不代表所有服务版本、认证方式或网络条件都已验证。以实际交付说明和服务要求为准。</p><h2 id="_2-保存和测试分别确认" tabindex="-1">2. 保存和测试分别确认 <a class="header-anchor" href="#_2-保存和测试分别确认" aria-label="Permalink to &quot;2. 保存和测试分别确认&quot;">​</a></h2><p>各类型操作见<a href="/induframe-docs/zh/guide/mqtt-datapoints.html">MQTT</a>、<a href="/induframe-docs/zh/guide/kafka-outputs.html">Kafka</a>、<a href="/induframe-docs/zh/guide/http-outputs.html">HTTP</a>、<a href="/induframe-docs/zh/guide/websocket-outputs.html">WebSocket</a>、<a href="/induframe-docs/zh/guide/redis-datapoints.html">Redis</a>和<a href="/induframe-docs/zh/guide/tdengine-queries.html">TDengine</a>。</p><p>填写便于识别的名称和对应参数。提供“测试连接”的类型，可先测试，检查具体结果，再点击 <strong>“创建连接”</strong>。</p><p>创建后回到列表，核对名称、类型、配置状态和最近测试结果。<strong>测试成功不等于已经保存，保存成功也不等于连接已通过验证。</strong> 提示已保存但测试失败时，先在已有连接上检查，不重复新建。</p><p>列表支持搜索、类型筛选以及卡片和列表视图。找不到连接时，先检查筛选与页码；加载失败先重试，不把未加载当作已删除。</p><h2 id="_3-打开工作台继续配置" tabindex="-1">3. 打开工作台继续配置 <a class="header-anchor" href="#_3-打开工作台继续配置" aria-label="Permalink to &quot;3. 打开工作台继续配置&quot;">​</a></h2><p>打开目标连接，按类型进入查询、消息、接口或实时数据工作台。</p><p>数据库连接存在，并不会自动把所有表都变成数据点。需要在工作台准备查询及输出；HTTP、WebSocket 等类型也要配置实际请求或会话。查看结果时同时确认来源、类型与时间，不能只看一个示例数值。</p><h2 id="_4-编辑和删除" tabindex="-1">4. 编辑和删除 <a class="header-anchor" href="#_4-编辑和删除" aria-label="Permalink to &quot;4. 编辑和删除&quot;">​</a></h2><p>允许编辑的连接使用 <strong>“编辑”</strong>，完成后点击 <strong>“保存修改”</strong>。密码提示“已保存，留空保持不变”时，不需要反复填写原密码；更改前确认实际服务凭据。</p><p>系统内置接入源受到保护，可能不显示编辑或删除操作。需要调整时请维护人员确认，不直接修改平台内部数据库配置。</p><p>删除前阅读依赖和影响提示：来源内配置可能被删除，已生成数据点可能保留为失效项。先处理阻止删除的引用，确认无需保留后再执行，不把删除重建当作修复连接的常规办法。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>先核对什么</th></tr></thead><tbody><tr><td>超时或无法连接</td><td>平台开发环境到服务的网络、实际地址与端口</td></tr><tr><td>认证失败</td><td>服务账号、凭据及该账号的访问范围</td></tr><tr><td>证书失败</td><td>服务证书、主机名和校验要求，不靠关闭校验继续</td></tr><tr><td>连接成功但看不到表或数据</td><td>所选库、Schema、账号权限及实际查询</td></tr><tr><td>保存结果不明确</td><td>刷新已有列表和对象，不立即重复创建</td></tr></tbody></table><p>不要把浏览器电脑的 <code>localhost</code> 当成远程数据库地址。求助时提供工程、连接类型、名称和脱敏提示，不交付密码或私钥。</p><p>下一步：<a href="/induframe-docs/zh/guide/builtin-stores.html">内置库</a> · <a href="/induframe-docs/zh/guide/mysql.html">MySQL</a> · <a href="/induframe-docs/zh/guide/datapoints.html">数据点列表</a>。</p>',23)])])}const m=e(o,[["render",h]]);export{p as __pageData,m as default};
